/bin/bash -lc "python - <<'PY'
import ast, pathlib
files = [
'/home/lixinyu/snap/new/ARC_code/train/e729b7be.py',
'/home/lixinyu/snap/new/ARC_code/train/f0f8a26d.py',
'/home/lixinyu/snap/new/ARC_code/train/9b30e358.py',
'/home/lixinyu/snap/new/ARC_code/train/fc4aaf52.py',
]
for path in files:
    src = pathlib.Path(path).read_text()
    mod = ast.parse(src)
    lines = src.splitlines()
    print(f'FILE {path}')
    for node in mod.body:
        if isinstance(node, ast.FunctionDef) and node.name in {'main','generate_input'}:
            start, end = node.lineno, node.end_lineno
            print(f'--- {node.name} {start}-{end} ---')
            span = end-start+1
            if span <= 120:
                rng = range(start, end+1)
            else:
                rng = list(range(start, min(start+79, end)+1)) + ['...'] + list(range(max(end-39, start), end+1))
            for item in rng:
                if item == '...':
                    print('...')
                else:
                    print(f'{item:04d}: {lines[item-1]}')
    print()
PY"

